package team.unnamed.mocha.runtime.program;

import team.unnamed.mocha.parser.ast.*;
import team.unnamed.mocha.runtime.*;
import team.unnamed.mocha.runtime.binding.JavaFunction;
import team.unnamed.mocha.runtime.value.*;
import java.util.*;

/** Runtime bridge for dynamic host functions; math and control flow live in generated bytecode. */
public abstract class CompiledRuntime implements Program {
    private Expression[] expressions;
    private byte[] bytes;
    private int[][] argumentNodes;
    private Value[] constants;
    private String[] names;
    final void initialize(Expression[] expressions, byte[] bytes, int[][] argumentNodes) {
        this.expressions = expressions; this.bytes = bytes; this.argumentNodes = argumentNodes;
        constants=new Value[expressions.length];names=new String[expressions.length];
        for(int i=0;i<expressions.length;i++) {
            Expression e=expressions[i];
            if(e instanceof DoubleExpression)constants[i]=NumberValue.of(((DoubleExpression)e).value());
            else if(e instanceof StringExpression)constants[i]=StringValue.of(((StringExpression)e).value());
            else if(e instanceof IdentifierExpression)names[i]=((IdentifierExpression)e).name();
            else if(e instanceof AccessExpression)names[i]=((AccessExpression)e).property();
        }
    }
    public final Value constant(int index) { return constants[index]; }
    public final String name(int index) { return names[index]; }
    public final int nodeCount() { return expressions.length; }
    public final int bytecodeSize() { return bytes.length; }
    public final byte[] bytecode() { return bytes.clone(); }
    public abstract boolean complex();
    public abstract Value run(Frame frame);
    public abstract Value node(int index, Frame frame);
    public abstract Value body(int index, Frame frame);
    public final Value evaluate(Object entity, Scope scope) {
        Frame frame = new Frame(this, entity, Objects.requireNonNull(scope, "scope"));
        Value result = run(frame);
        return frame.returned != null ? frame.returned : RuntimeSemantics.value(result);
    }
    public final Value evaluateFresh(Object entity, Scope scope) {
        Scope local = scope.copy(); MutableObjectBinding temp = new MutableObjectBinding();
        local.set("temp",temp); local.set("t",temp); local.readOnly(true);
        Frame frame=new Frame(this,entity,local);
        Value result=run(frame);
        return frame.returned!=null?frame.returned:complex()?NumberValue.zero():RuntimeSemantics.value(result);
    }
    public final Value block(final int index, final Frame frame) {
        return (Function<Object>)(context,args) -> {
            if (!(context instanceof Frame)) throw new IllegalArgumentException("Compiled block requires its execution frame");
            body(index,(Frame)context); return NumberValue.zero();
        };
    }
    public final Value call(int index, final Frame frame, Value function) {
        final int[] arguments = argumentNodes[index];
        if (!(function instanceof Function)) return Value.nil();
        NumericFunction numeric=function instanceof NumericFunction?(NumericFunction)function:
                function instanceof JavaFunction?((JavaFunction<?>)function).numeric():null;
        if(numeric!=null) {
            int count=numeric.arity();
            if(count<0||count>3)throw new IllegalArgumentException("NumericFunction arity must be 0..3");
            double a=count>0&&arguments.length>0?node(arguments[0],frame).getAsNumber():0;
            double b=count>1&&arguments.length>1?node(arguments[1],frame).getAsNumber():0;
            double c=count>2&&arguments.length>2?node(arguments[2],frame).getAsNumber():0;
            return NumberValue.of(numeric.invoke(a,b,c));
        }
        final List<Expression> source = ((CallExpression)expressions[index]).arguments();
        Function.Arguments values = new Function.Arguments() {
            int cursor;
            public int length() { return arguments.length; }
            public Function.Argument next() {
                if (cursor >= arguments.length) return Function.Arguments.empty().next();
                final int ordinal = cursor++;
                return new Function.Argument() {
                    public Expression expression() { return new AstSnapshot().copy(source.get(ordinal)); }
                    public Value eval() { return node(arguments[ordinal],frame); }
                };
            }
        };
        return RuntimeSemantics.value(((Function<Object>)function).evaluate(frame,values));
    }
    public static Value executeBlock(Value value, Frame frame) {
        return value instanceof Function ? RuntimeSemantics.value(((Function<Object>)value).evaluate(frame)) : value;
    }
    public static final class Frame implements ExecutionContext<Object> {
        public final Object actor;
        public final Scope scope;
        public Value returned;
        public Object control;
        Frame(CompiledRuntime program,Object actor,Scope scope) { this(actor,scope,new int[]{1048576}); }
        public Frame child(Object actor) { return new Frame(actor,scope,budget); }
        public Frame actorChild(Value reference) {
            Object entity=RuntimeSemantics.actor(reference);
            return entity==null?null:new Frame(entity,RuntimeSemantics.actorScope(reference,scope),budget);
        }
        private Frame(Object actor,Scope scope,int[] budget) { this.actor=actor;this.scope=scope;this.budget=budget; }
        private final int[] budget;
        public void iteration() { if(--budget[0]<0)throw new IllegalStateException("Molang evaluation loop budget exceeded"); }
        public boolean stopped() { return returned != null || control != null; }
        public Object entity() { return actor; }
        public Object flag() { return control; }
        public void flag(Object flag) { control=flag; }
        public Value eval(Expression expression) {
            // Expression-sensitive extension API: compile its supplied AST before execution.
            CompiledRuntime code=(CompiledRuntime)ProgramCompiler.shared().compile(Collections.singletonList(expression));
            Value result=code.run(this);
            return RuntimeSemantics.value(result);
        }
    }
}
